// src/Telas/Home.js
import React from 'react';
import '../Estilo/Home.css'; // Importa o CSS para a página inicial, se necessário

function Home() {
  return (
    <div className="home-container">
      <h1>Bem-vindo ao nosso aplicativo!</h1>
      <p>Aqui você pode cadastrar e visualizar seus dados.</p>
    </div>
  );
}

export default Home;
